INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('8d16edfb-0095-4af1-a2f8-ff254eb863c0', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1008', 'Orbit 1080p Webcam', 'orbit-webcam-clip', 'A 1080p webcam with a wide-angle lens and a privacy shutter that actually stays shut.', 'Orbit''s autofocus keeps up with normal fidgeting, and the low-light correction means you don''t look like you''re calling from a cave once the sun goes down.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('e2e26e67-a060-49bf-8e34-2ade156dd854', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-DSK-1009', 'Anchor 3-in-1 Charging Dock', 'anchor-charging-dock', 'Charges phone, watch and earbuds at once, angled so you can still see notifications.', 'Anchor holds a phone at an angle that keeps Face ID and notifications visible while it charges, with a dedicated puck for a smartwatch and a slot underneath for an earbuds case.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('0c6fcc2d-04ce-4de8-9224-785937f28dfd', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-PWR-1010', 'Voltpack 20,000mAh Power Bank', 'voltpack-power-bank', 'Enough capacity for four full phone charges, with pass-through so it charges itself and your laptop at the same time.', 'Voltpack''s 20,000mAh cell is enough to take a phone from empty to full about four times, or top off a laptop once with enough left over for a phone.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('3a93996c-61ee-46d8-b723-9fb11d01413d', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-PWR-1011', 'Driftcase 1TB Portable SSD', 'driftcase-portable-ssd', 'A 1TB solid-state drive rated to survive a 2-meter drop, with transfer speeds fast enough for 4K video editing.', 'Driftcase reads at up to 1,050MB/s, fast enough to edit 4K footage directly off the drive instead of copying it over first. The aluminum shell is rated for a 2-meter drop onto a hard surface.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('7143d53a-3a3a-40cb-ba66-2e068fa09796', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-WBL-1012', 'Pulse Smartwatch', 'pulse-smartwatch', 'A smartwatch with a seven-day battery, GPS, and a screen bright enough to read in direct sun.', 'Pulse tracks heart rate, sleep and about thirty workout types, and holds a charge for a full week between charges — the display stays on the whole time, not just on wrist-raise.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('fa9739b0-c5df-4d09-b6ce-313718ff8351', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-CND-2004', 'Amber Fields Soy Candle', 'amber-fields-candle', 'A single-wick soy candle in amber, cedar and a little black pepper. Burns about 45 hours.', 'Amber Fields is our best-selling scent for a reason — warm without being sweet, and it doesn''t turn cloying halfway through the jar the way a lot of amber candles do.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('cdf1c576-19ab-4eca-8df6-92009003ec0e', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-CND-2005', 'Orchard Candle Trio', 'orchard-candle-trio', 'Three 4oz candles — apple, fig and spiced pear — sized for testing scents before committing to a full jar.', 'The Orchard trio is how most people find their favorite Fernwood scent. Each jar is a quarter of our standard size, enough for about 15 hours of burn time, which is plenty to decide whether fig belongs on your shelf permanently.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('7f3a2fe0-eeb2-4a48-81a4-16b1abe5a2e4', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-POT-2001', 'Hearth Ceramic Mug', 'hearth-ceramic-mug', 'A 12oz stoneware mug, thrown and glazed by hand — no two exactly alike.', 'Each Hearth mug starts as a lump of stoneware clay on Priya''s wheel and comes off it twenty minutes later shaped, though not yet fired. The reactive glaze runs differently every time it hits the kiln, so the mug you get is the only one exactly like it.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('876fb3f7-d6a6-446d-af41-aa70d0788e47', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-POT-2002', 'Bud Ceramic Vase', 'bud-ceramic-vase', 'A single-stem bud vase in a hand-mixed matte glaze, tall enough for a branch, small enough for a windowsill.', 'Bud vases are thrown one at a time on a slow wheel, which is why we can only make about fifteen a week. The narrow neck holds a single stem upright without the vase tipping, which is harder to get right than it sounds.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('265a6282-2840-4d39-b8ab-5eff8ba3558d', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-POT-2003', 'Nested Ceramic Bowl Set (3)', 'nested-ceramic-bowls', 'Three stoneware bowls in graduated sizes that nest for storage and stack for the shelf.', 'This set covers cereal, soup and serving in one glaze run, so the three bowls actually match instead of being assembled from different batches after the fact.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('ca9fb776-82b0-4386-bb20-8cea1e224a84', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2006', 'Harvest Woven Tote', 'harvest-woven-tote', 'A market tote hand-loomed from cotton and jute, sturdy enough for actual groceries.', 'This isn''t a decorative tote — the jute base and cotton weave are rated to carry real weight, and we''ve tested it with two full grocery bags'' worth without the seams complaining.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('00140444-a83d-4724-8b3d-e4ee7934a0cf', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2007', 'Cabin Wool Throw', 'cabin-wool-throw', 'A 50x60 lambswool throw, woven on a floor loom in a three-color stripe pattern.', 'Cabin is woven from lambswool on a floor loom, in three colorways that rotate with the seasons. It''s substantial — closer to a blanket than a scarf-weight throw — and holds up to years of actual couch use.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('fc1527a0-4c23-4be4-9d58-ec1e68c75200', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2008', 'Market Linen Apron', 'market-linen-apron', 'A cross-back linen apron with one deep pocket, cut generously enough to actually protect your clothes.', 'The cross-back straps mean this apron stays put without a neck loop cutting into you after an hour of standing at the counter. Heavyweight linen softens with every wash instead of wearing thin.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('32ccad60-d966-4236-a8c5-308e8a223127', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-TEX-2009', 'Driftwood Macrame Hanging', 'driftwood-macrame-hanging', 'A knotted cotton-cord wall hanging on a foraged driftwood dowel, about 22 inches long.', 'Each dowel is foraged, not milled, so the wood grain and curve are different on every piece — you''re choosing a specific dowel, not a style number.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('8c5bdf88-42e1-4639-a14d-0670f9626a8d', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-WD-2010', 'Maple End-Grain Cutting Board', 'maple-cutting-board', 'An end-grain maple board that''s easier on knife edges than a face-grain board twice its price.', 'End-grain construction means the wood fibers face up, so a knife edge slides between them instead of across them — it''s genuinely easier on your knives, not just a marketing distinction.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('0a13c2b0-3e93-4d31-96a5-d7e60eb42f8f', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-WD-2011', 'Fieldnote Leather Journal', 'fieldnote-leather-journal', 'A refillable leather journal with 160 pages of Italian paper and a brass closure.', 'The vegetable-tanned cover develops a patina with handling — the one on the shelf sample looks nothing like the one that shipped a year ago, and that''s the point.
INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('85eb9fb9-c14e-48d7-8e44-c0dc6da6e7c5', '650e8400-e29b-41d4-a716-446655440002', NULL, 'FWG-WD-2012', 'Birchwood Spoon Set (3)', 'birchwood-spoon-set', 'Three hand-carved birchwood cooking spoons in different profiles — stirring, serving, and a slotted spoon.', 'Each spoon is carved from a single piece of birch, no glued laminations to eventually split. The slotted spoon''s holes are burned through, not drilled, which leaves a smoother edge against a pan.
